using System.Collections.Generic;
using UnityEngine;
using Flynn.Npc.Memory;

// Loads one island JSON (authored under Assets/Flynn/Configs/NPC/Islands/)
// and exposes simple id-keyed lookups. No SO, no singleton — drop the
// component on a scene root and reference it from SceneLlmManager (or
// query it directly) when the resolver lands.
//
// Lookups are rebuilt on Awake and on any LoadFrom call so designers can
// hot-swap content in the editor without restarting Play.
public class IslandContentHub : MonoBehaviour
{
    [Tooltip("Authored island content. Drop the .json TextAsset (e.g. windroot_hamlet.json) here.")]
    public TextAsset islandJson;

    private IslandContent _content;
    private readonly Dictionary<string, NpcContent> _npcById = new Dictionary<string, NpcContent>(StringComparer.Ordinal);
    private readonly Dictionary<string, WorldThingContent> _thingById = new Dictionary<string, WorldThingContent>(StringComparer.Ordinal);
    private readonly Dictionary<string, WorldThingContent> _thingByAlias = new Dictionary<string, WorldThingContent>(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, SignalContent> _signalById = new Dictionary<string, SignalContent>(StringComparer.Ordinal);
    private readonly Dictionary<string, List<SignalContent>> _signalsByThing = new Dictionary<string, List<SignalContent>>(StringComparer.Ordinal);

    public IslandContent Content => _content;
    public bool IsLoaded => _content != null;

    private void Awake()
    {
        if (islandJson != null) LoadFrom(islandJson);
    }

    public bool LoadFrom(TextAsset asset)
    {
        if (asset == null) { Clear(); return false; }
        return LoadFromJson(asset.text, asset.name);
    }

    public bool LoadFromJson(string json, string sourceLabel = "(inline)")
    {
        Clear();
        if (string.IsNullOrWhiteSpace(json))
        {
            Debug.LogWarning("[IslandContentHub] Empty island JSON: " + sourceLabel);
            return false;
        }
        try { _content = JsonUtility.FromJson<IslandContent>(json); }
        catch (Exception e)
        {
            Debug.LogError("[IslandContentHub] Failed to parse island JSON '" + sourceLabel + "': " + e.Message);
            _content = null;
            return false;
        }
        if (_content == null)
        {
            Debug.LogError("[IslandContentHub] JsonUtility returned null for '" + sourceLabel + "'.");
            return false;
        }
        BuildIndices();
        return true;
    }

    // Rebuilds the runtime content from the unified LiteDB instead of JSON. JSON
    // remains the canonical seed (the importer mirrors it into the DB); this makes
    // the DB the runtime source so authored edits + future DB-only content flow
    // through the same resolver/prompt path. POCO shapes are unchanged, so no
    // downstream consumer is affected.
    public bool LoadFromDatabase(NpcMemoryDatabase db, string islandId)
    {
        var content = IslandContentDb.ToContent(db, islandId);
        if (content == null) return false;
        Clear();
        _content = content;
        BuildIndices();
        Debug.Log($"[IslandContentHub] Loaded '{islandId}' from DB: {content.npcs.Count} npcs, {content.things.Count} things, {content.signals.Count} signals.");
        return true;
    }

    private void BuildIndices()
    {
        if (_content.npcs != null)
        {
            foreach (var n in _content.npcs)
            {
                if (n == null || string.IsNullOrEmpty(n.npcId)) continue;
                _npcById[n.npcId] = n;
            }
        }
        if (_content.things != null)
        {
            foreach (var t in _content.things)
            {
                if (t == null || string.IsNullOrEmpty(t.thingId)) continue;
                _thingById[t.thingId] = t;
                if (!string.IsNullOrWhiteSpace(t.displayName))
                    _thingByAlias[t.displayName.Trim()] = t;
                if (t.aliases != null)
                {
                    foreach (var alias in t.aliases)
                    {
                        if (string.IsNullOrWhiteSpace(alias)) continue;
                        _thingByAlias[alias.Trim()] = t;
                    }
                }
            }
        }
        if (_content.signals != null)
        {
            foreach (var s in _content.signals)
            {
                if (s == null || string.IsNullOrEmpty(s.signalId)) continue;
                _signalById[s.signalId] = s;
                string key = s.thingId ?? string.Empty;
                if (!_signalsByThing.TryGetValue(key, out var list))
                {
                    list = new List<SignalContent>();
                    _signalsByThing[key] = list;
                }
                list.Add(s);
            }
        }
    }

    private void Clear()
    {
        _content = null;
        _npcById.Clear();
        _thingById.Clear();
        _thingByAlias.Clear();
        _signalById.Clear();
        _signalsByThing.Clear();
    }

    // ── Queries ──────────────────────────────────────────────────────────────

    public NpcContent GetNpc(string npcId)
    {
        if (string.IsNullOrEmpty(npcId)) return null;
        _npcById.TryGetValue(npcId, out var npc);
        return npc;
    }

    public WorldThingContent GetThing(string thingId)
    {
        if (string.IsNullOrEmpty(thingId)) return null;
        _thingById.TryGetValue(thingId, out var thing);
        return thing;
    }

    public CommunityContent GetCommunity() => _content != null ? _content.community : null;

    public SignalContent GetSignal(string signalId)
    {
        if (string.IsNullOrEmpty(signalId)) return null;
        _signalById.TryGetValue(signalId, out var s);
        return s;
    }

    // Signals tied to a given thing. Pass empty string to fetch the
    // "no-thing" bucket (things like first-meeting beats).
    public IReadOnlyList<SignalContent> GetSignalsForThing(string thingId)
    {
        string key = thingId ?? string.Empty;
        return _signalsByThing.TryGetValue(key, out var list)
            ? (IReadOnlyList<SignalContent>)list
            : Array.Empty<SignalContent>();
    }

    // Best-effort alias resolution. Tries exact-case thingId first, then
    // case-insensitive alias/displayName match. Returns null if nothing
    // looks plausible. Substring scans live in the resolver, not here.
    public WorldThingContent ResolveByAlias(string text)
    {
        if (string.IsNullOrWhiteSpace(text)) return null;
        string trimmed = text.Trim();
        if (_thingById.TryGetValue(trimmed, out var direct)) return direct;
        return _thingByAlias.TryGetValue(trimmed, out var byAlias) ? byAlias : null;
    }

    public IEnumerable<KnowledgeContent> GetNpcKnowledgeForThing(string npcId, string thingId, int trust)
    {
        var npc = GetNpc(npcId);
        if (npc == null || npc.knowledge == null) yield break;
        foreach (var k in npc.knowledge)
        {
            if (k == null || string.IsNullOrWhiteSpace(k.text)) continue;
            if (!string.IsNullOrEmpty(thingId) && !string.Equals(k.thingId, thingId, StringComparison.Ordinal)) continue;
            if (k.revealTrustThreshold > 0 && trust < k.revealTrustThreshold) continue;
            yield return k;
        }
    }

    public IEnumerable<KnowledgeContent> GetCommunityKnowledgeForThing(string thingId, int trust)
    {
        var community = GetCommunity();
        if (community == null || community.knowledge == null) yield break;
        foreach (var k in community.knowledge)
        {
            if (k == null || string.IsNullOrWhiteSpace(k.text)) continue;
            if (!string.IsNullOrEmpty(thingId) && !string.Equals(k.thingId, thingId, StringComparison.Ordinal)) continue;
            if (k.revealTrustThreshold > 0 && trust < k.revealTrustThreshold) continue;
            yield return k;
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using LiteDB;
using UnityEngine;

namespace Flynn.Npc.Memory
{
    // Thin wrapper over a single LiteDB file holding one save slot's NPC memory.
    // Owns the connection lifecycle (Open/Dispose), exposes typed helpers for the
    // collections used this pass, and a generic GetCollection<T> so future doc
    // types (relationships, player state) slot in without touching this class.
    //
    // Vectors are stored on the documents; recall is a brute-force cosine over a
    // Find-filtered candidate set — fast at NPC scale, no native vector index.
    public class NpcMemoryDatabase : IDisposable
    {
        public const int SchemaVersion = 1;

        private LiteDatabase _db;
        private string _path;

        public bool IsOpen => _db != null;
        public string Path => _path;

        // One recalled item ready to render into the prompt's memory block.
        public struct RecalledItem
        {
            public string Text;
            public string Subject;  // memory subject tag, or "knowledge"
            public string Source;   // dialogue | authored | gossip | knowledge
            public float Score;
        }

        // ── Lifecycle ─────────────────────────────────────────────────────────

        public static string SlotDir(string slotId)
        {
            string slot = string.IsNullOrWhiteSpace(slotId) ? "slot_0" : slotId.Trim();
            return System.IO.Path.Combine(Application.persistentDataPath, "npc_memory", slot);
        }

        public static string SlotDbPath(string slotId) =>
            System.IO.Path.Combine(SlotDir(slotId), "npc_memory.db");

        // Slot ids that have a DB file on disk (dir names under npc_memory/).
        public static IEnumerable<string> EnumerateSlots()
        {
            string root = System.IO.Path.Combine(Application.persistentDataPath, "npc_memory");
            if (!Directory.Exists(root)) yield break;
            foreach (var dir in Directory.GetDirectories(root))
                if (File.Exists(System.IO.Path.Combine(dir, "npc_memory.db")))
                    yield return System.IO.Path.GetFileName(dir);
        }

        // Opens (creating if needed) the DB file for a slot under persistentDataPath.
        public void Open(string slotId, string embeddingModel, int dim)
        {
            OpenInternal(slotId);
            EnsureIndices();
            EnsureMeta(embeddingModel, dim);
        }

        // Opens an existing slot DB for read/manage (browser/editor) without
        // writing meta. Returns false if the file doesn't exist.
        public bool OpenExisting(string slotId)
        {
            if (!File.Exists(SlotDbPath(slotId))) return false;
            OpenInternal(slotId);
            return true;
        }

        private void OpenInternal(string slotId)
        {
            Dispose();
            Directory.CreateDirectory(SlotDir(slotId));
            _path = SlotDbPath(slotId);
            // Shared connection so an external LiteDB browser (or a second
            // in-process connection) can open the file while the game holds it.
            _db = new LiteDatabase(new ConnectionString { Filename = _path, Connection = ConnectionType.Shared });
        }

        private void EnsureIndices()
        {
            Memories.EnsureIndex(x => x.NpcId);
            Knowledge.EnsureIndex(x => x.OwnerScope);
            Knowledge.EnsureIndex(x => x.ContentHash);
            ChatTurns.EnsureIndex(x => x.NpcId);
            Things.EnsureIndex(x => x.ThingId);
            Npcs.EnsureIndex(x => x.NpcId);
            Signals.EnsureIndex(x => x.SignalId);
            Community.EnsureIndex(x => x.CommunityId);
        }

        private void EnsureMeta(string embeddingModel, int dim)
        {
            var col = Meta;
            var meta = col.FindById(1);
            if (meta == null)
            {
                col.Insert(new MetaDoc { Id = 1, SchemaVersion = SchemaVersion, EmbeddingModel = embeddingModel, Dim = dim });
                return;
            }
            if (!string.Equals(meta.EmbeddingModel, embeddingModel, StringComparison.Ordinal) || meta.Dim != dim)
                Debug.LogWarning(string.Format(
                    "[NpcMemoryDatabase] DB was built with embedding model '{0}' ({1}-dim) but current settings are '{2}' ({3}-dim). " +
                    "Stored vectors won't be comparable to new ones — re-embed or clear the DB.",
                    meta.EmbeddingModel, meta.Dim, embeddingModel, dim));
        }

        public void Dispose()
        {
            if (_db != null) { _db.Dispose(); _db = null; }
        }

        // ── Collection accessors ──────────────────────────────────────────────

        public ILiteCollection<MemoryDoc> Memories  => _db.GetCollection<MemoryDoc>(MemoryCollections.Memories);
        public ILiteCollection<KnowledgeDoc> Knowledge => _db.GetCollection<KnowledgeDoc>(MemoryCollections.Knowledge);
        public ILiteCollection<ChatTurnDoc> ChatTurns => _db.GetCollection<ChatTurnDoc>(MemoryCollections.ChatTurns);
        public ILiteCollection<MetaDoc> Meta        => _db.GetCollection<MetaDoc>(MemoryCollections.Meta);

        // Authored entities.
        public ILiteCollection<CommunityDoc> Community => _db.GetCollection<CommunityDoc>(MemoryCollections.Community);
        public ILiteCollection<ThingDoc> Things        => _db.GetCollection<ThingDoc>(MemoryCollections.Things);
        public ILiteCollection<NpcDoc> Npcs            => _db.GetCollection<NpcDoc>(MemoryCollections.Npcs);
        public ILiteCollection<SignalDoc> Signals      => _db.GetCollection<SignalDoc>(MemoryCollections.Signals);

        // Generic escape hatch for doc types added later (RelationshipDoc, PlayerStateDoc).
        public ILiteCollection<T> GetCollection<T>(string name) => _db.GetCollection<T>(name);

        // Distinct NPC ids that have any dynamic data (memories or chat).
        public IEnumerable<string> DistinctNpcIds()
        {
            var set = new HashSet<string>(StringComparer.Ordinal);
            foreach (var m in Memories.FindAll()) if (!string.IsNullOrEmpty(m.NpcId)) set.Add(m.NpcId);
            foreach (var t in ChatTurns.FindAll()) if (!string.IsNullOrEmpty(t.NpcId)) set.Add(t.NpcId);
            return set;
        }

        // ── Memory writes ─────────────────────────────────────────────────────

        // Inserts a fact unless a near-duplicate (cosine >= dedupThreshold) already
        // exists for the same NPC + subject. Returns true if inserted.
        public bool TryInsertMemory(MemoryDoc doc, float dedupThreshold)
        {
            if (doc == null || string.IsNullOrWhiteSpace(doc.Text)) return false;

            if (doc.Embedding != null && doc.Embedding.Length > 0)
            {
                foreach (var existing in Memories.Find(x => x.NpcId == doc.NpcId && x.Subject == doc.Subject))
                {
                    if (existing.Embedding == null) continue;
                    if (VectorMath.Cosine(existing.Embedding, doc.Embedding) >= dedupThreshold)
                        return false;
                }
            }

            if (doc.CreatedUtc == default) doc.CreatedUtc = DateTime.UtcNow;
            Memories.Insert(doc);
            return true;
        }

        public void InsertChatTurn(ChatTurnDoc doc)
        {
            if (doc == null || string.IsNullOrWhiteSpace(doc.Content)) return;
            if (doc.CreatedUtc == default) doc.CreatedUtc = DateTime.UtcNow;
            ChatTurns.Insert(doc);
        }

        public int NextTurnIndex(string npcId)
        {
            int max = -1;
            foreach (var t in ChatTurns.Find(x => x.NpcId == npcId))
                if (t.TurnIndex > max) max = t.TurnIndex;
            return max + 1;
        }

        // ── Recall ────────────────────────────────────────────────────────────

        // Top-k blended-score recall over this NPC's memories + visible knowledge.
        // Bumps recall stats on the memories that survive into the result.
        public List<RecalledItem> Recall(string npcId, int trust, float[] queryVec, int topK, float minSimilarity)
        {
            var results = new List<RecalledItem>();
            if (_db == null || queryVec == null || queryVec.Length == 0 || string.IsNullOrEmpty(npcId))
                return results;

            DateTime now = DateTime.UtcNow;
            var scoredMemories = new List<KeyValuePair<MemoryDoc, float>>();

            foreach (var m in Memories.Find(x => x.NpcId == npcId))
            {
                if (m.Embedding == null) continue;
                float sim = VectorMath.Cosine(queryVec, m.Embedding);
                if (sim < minSimilarity) continue;

                float importanceBoost = 0.05f * Mathf.Clamp(m.Importance, 0f, 5f);
                double ageDays = (now - m.CreatedUtc).TotalDays;
                float recencyBoost = Mathf.Clamp01(1f - (float)(ageDays / 30.0)) * 0.1f;
                float score = sim + importanceBoost + recencyBoost;

                scoredMemories.Add(new KeyValuePair<MemoryDoc, float>(m, score));
                results.Add(new RecalledItem { Text = m.Text, Subject = m.Subject, Source = m.Source, Score = score });
            }

            foreach (var k in Knowledge.Find(x => x.OwnerScope == npcId || x.OwnerScope == "community"))
            {
                if (k.Embedding == null) continue;
                if (k.RevealTrust > 0 && trust < k.RevealTrust) continue;
                float sim = VectorMath.Cosine(queryVec, k.Embedding);
                if (sim < minSimilarity) continue;
                results.Add(new RecalledItem { Text = k.Text, Subject = "knowledge", Source = "knowledge", Score = sim });
            }

            results.Sort((a, b) => b.Score.CompareTo(a.Score));
            if (topK > 0 && results.Count > topK) results.RemoveRange(topK, results.Count - topK);

            // Bump recall stats for memories that made the cut.
            var keep = new HashSet<string>();
            foreach (var r in results) keep.Add(r.Text);
            foreach (var kv in scoredMemories)
            {
                if (!keep.Contains(kv.Key.Text)) continue;
                kv.Key.LastRecalledUtc = now;
                kv.Key.RecallCount += 1;
                Memories.Update(kv.Key);
            }

            return results;
        }

        // ── Stats (for HUD / editor read-outs) ────────────────────────────────

        public int CountMemories(string npcId)
        {
            if (_db == null || string.IsNullOrEmpty(npcId)) return 0;
            return Memories.Count(x => x.NpcId == npcId);
        }

        public int CountChatTurns(string npcId)
        {
            if (_db == null || string.IsNullOrEmpty(npcId)) return 0;
            return ChatTurns.Count(x => x.NpcId == npcId);
        }

        // Most recent chat turn's text for this NPC, or "" if none.
        public string GetLastChatTurnText(string npcId)
        {
            if (_db == null || string.IsNullOrEmpty(npcId)) return "";
            ChatTurnDoc latest = null;
            foreach (var t in ChatTurns.Find(x => x.NpcId == npcId))
                if (latest == null || t.TurnIndex > latest.TurnIndex) latest = t;
            return latest != null ? latest.Content : "";
        }

        // ── Maintenance ───────────────────────────────────────────────────────

        public void ClearNpc(string npcId)
        {
            if (string.IsNullOrEmpty(npcId)) return;
            Memories.DeleteMany(x => x.NpcId == npcId);
            ChatTurns.DeleteMany(x => x.NpcId == npcId);
        }

        public void ClearAllMemory()
        {
            Memories.DeleteAll();
            ChatTurns.DeleteAll();
        }
    }
}

using UnityEngine;

/// <summary>
/// DEPRECATED — superseded by <see cref="WorldItem"/> (+ <see cref="DroppedItemMagnet"/> for
/// auto-collect, key-pickup via <see cref="PlayerMouseAimer.HoveredKeyPickup"/>). Kept only so the
/// retired UI-Toolkit HUDs still compile; new prefabs should use <see cref="WorldItem"/> instead.
///
/// Marks a world object as something the player can pick up. Detection is by mouse raycast in
/// <see cref="PlayerMouseAimer"/> — no registry, no trigger volume. The collider must be a
/// SOLID (non-trigger) collider on a layer in the aimer's pickup mask so the ray can hit it.
/// </summary>
[RequireComponent(typeof(Collider))]
public class WorldItemPickup : MonoBehaviour
{
    [Tooltip("The item definition granted to the player's inventory on pickup.")]
    [SerializeField] private ItemDefinition _item;

    public ItemDefinition Item => _item;
}

using UnityEngine;

/// <summary>
/// The single droppable / pickupable unit in the world: an <see cref="ItemDefinition"/> plus a
/// stack count. Everything that can sit on the ground — resource drops, echo shards, the wrench,
/// items dropped from the inventory — is a WorldItem. Auto-collecting items are pulled in by
/// <see cref="DroppedItemMagnet"/>; non-auto items (the wrench) are picked up with the pickup key
/// via <see cref="PlayerMouseAimer"/>/<see cref="PlayerPickupController"/>.
///
/// Detection is by mouse raycast (solid, non-trigger collider on the pickup layer) — no registry.
/// </summary>
[RequireComponent(typeof(Collider))]
public class WorldItem : MonoBehaviour, IInteractionPromptProvider
{
    [Tooltip("Item this world object represents.")]
    [SerializeField] private ItemDefinition _item;

    [Tooltip("How many of the item this stack holds.")]
    [SerializeField] private int _count = 1;

    public ItemDefinition Item => _item;
    public int Count => _count;

    /// <summary>Set the item + count, e.g. when spawned by <see cref="WorldItemSpawner"/>.</summary>
    public void Configure(ItemDefinition item, int count)
    {
        _item = item;
        _count = Mathf.Max(1, count);
    }

    /// <summary>Reduce the stack after a partial collection; returns the remaining count.</summary>
    public int Reduce(int amount)
    {
        _count = Mathf.Max(0, _count - Mathf.Max(0, amount));
        return _count;
    }

    // Only key-pickup items prompt; auto-collect drops fly in on their own (no prompt).
    public bool TryGetPrompt(out InteractionPrompt prompt)
    {
        if (_item == null || _item.AutoCollects)
        {
            prompt = default;
            return false;
        }
        prompt = new InteractionPrompt("E", "Pick Up", transform, _item.displayName);
        return true;
    }
}

using UnityEngine;

/// <summary>
/// Single entry point for putting an item into the world. Resource drops, echo-shard rolls, the
/// drop key and drag-to-drop all spawn through here so there's one place that wires up the
/// WorldItem + the initial "pop" physics. The prefab is resolved from the item itself
/// (<see cref="ItemDefinition.worldPrefab"/>), so callers only need the item + count.
/// </summary>
public static class WorldItemSpawner
{
    /// <summary>
    /// Spawn a stack of <paramref name="item"/> at <paramref name="position"/>. Optionally apply an
    /// upward "pop" impulse (requires a Rigidbody on the prefab) so drops scatter and settle.
    /// Returns the spawned WorldItem, or null if the item has no world prefab.
    /// </summary>
    public static WorldItem Spawn(ItemDefinition item, int count, Vector3 position, float popImpulse = 0f)
    {
        if (item == null || item.worldPrefab == null || count <= 0) return null;

        GameObject go = Object.Instantiate(item.worldPrefab, position, Quaternion.identity);

        WorldItem worldItem = go.GetComponent<WorldItem>();
        if (worldItem != null) worldItem.Configure(item, count);

        if (popImpulse > 0f)
        {
            Rigidbody rb = go.GetComponent<Rigidbody>();
            if (rb != null && !rb.isKinematic)
            {
                Vector3 dir = (Vector3.up + 0.45f * Random.insideUnitSphere).normalized;
                rb.AddForce(dir * popImpulse, ForceMode.Impulse);
            }
        }

        return worldItem;
    }
}

using UnityEngine;

/// <summary>
/// Pulls an auto-collecting <see cref="WorldItem"/> to the player after a short settle delay, then
/// collects it: resources/items go to the inventory, currencies to their counter. If the inventory
/// has no room the item idles on the ground and re-checks periodically (VS-style gem behaviour).
///
/// Finds the player through a <see cref="PlayerAnchor"/> SO — no FindObjectOfType. Non-auto items
/// (the wrench) disable this component and are picked up with the pickup key instead.
/// </summary>
[RequireComponent(typeof(WorldItem))]
public class DroppedItemMagnet : MonoBehaviour
{
    [SerializeField] private PlayerAnchor _playerAnchor;

    [Header("Timing")]
    [Tooltip("Seconds the drop sits/settles before it may fly to the player.")]
    [SerializeField] private float _settleDelay = 0.6f;
    [Tooltip("How often to re-check for inventory room while waiting.")]
    [SerializeField] private float _roomRecheckInterval = 0.4f;

    [Header("Flight")]
    [SerializeField] private float _maxSpeed = 7f;
    [SerializeField] private float _acceleration = 16f;
    [SerializeField] private float _collectRadius = 0.55f;
    [SerializeField] private float _targetHeight = 0.6f;

    private WorldItem _item;
    private Rigidbody _rb;

    private float _age;
    private float _extraDelay;
    private float _recheckTimer;
    private float _speed;
    private bool _flying;

    /// <summary>
    /// Delay auto-collection by <paramref name="seconds"/> beyond the normal settle (used when the
    /// player drops an item so it doesn't instantly fly back). Takes the longer of any pending delay.
    /// </summary>
    public void Suppress(float seconds)
    {
        _extraDelay = Mathf.Max(_extraDelay, seconds);
        _flying = false;
    }

    private void Awake()
    {
        _item = GetComponent<WorldItem>();
        _rb = GetComponent<Rigidbody>();
    }

    private void OnEnable()
    {
        _age = 0f;
        _extraDelay = 0f;
        _recheckTimer = 0f;
        _speed = 0f;
        _flying = false;
    }

    private void Update()
    {
        ItemDefinition def = _item != null ? _item.Item : null;
        if (def == null) return;

        // Non-auto items (wrench) wait for the pickup key — not our job.
        if (!def.AutoCollects) { enabled = false; return; }

        _age += Time.deltaTime;
        if (_age < _settleDelay + _extraDelay) return;

        Transform player = _playerAnchor != null ? _playerAnchor.Current : null;
        if (player == null) return;

        if (!_flying)
        {
            _recheckTimer -= Time.deltaTime;
            if (_recheckTimer > 0f) return;
            _recheckTimer = _roomRecheckInterval;
            if (!HasRoom(def, player)) return;
            BeginFlight();
        }

        _speed = Mathf.MoveTowards(_speed, _maxSpeed, _acceleration * Time.deltaTime);
        Vector3 target = player.position + Vector3.up * _targetHeight;
        transform.position = Vector3.MoveTowards(transform.position, target, _speed * Time.deltaTime);

        if (Vector3.Distance(transform.position, target) <= _collectRadius)
            Collect(def, player);
    }

    private bool HasRoom(ItemDefinition def, Transform player)
    {
        if (def.isCurrency) return true;
        return PlayerInventory.Instance != null && PlayerInventory.Instance.HasRoomFor(def);
    }

    private void BeginFlight()
    {
        _flying = true;
        if (_rb != null)
        {
            _rb.velocity = Vector3.zero;
            _rb.angularVelocity = Vector3.zero;
            _rb.isKinematic = true; // hand control to the magnet's MoveTowards
        }
    }

    private void Collect(ItemDefinition def, Transform player)
    {
        if (def.isCurrency)
        {
            if (def.currencyTarget != null) def.currencyTarget.Add(_item.Count);
            Destroy(gameObject);
            return;
        }

        int added = PlayerInventory.Instance != null ? PlayerInventory.Instance.TryAddItem(def, _item.Count) : 0;
        if (added >= _item.Count)
        {
            Destroy(gameObject);
            return;
        }

        // Inventory filled mid-flight: drop the remainder back on the ground and idle.
        if (added > 0) _item.Reduce(added);
        _flying = false;
        _speed = 0f;
        if (_rb != null) _rb.isKinematic = false;
    }
}

